# -*- coding: utf-8 -*-
from pathlib import Path
import html, json, hashlib
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'actual/reports/enemy-experience-20261104'
rules=json.loads((ROOT/'actual/data/enemy_experience_20261104.json').read_text())
result=json.loads((OUT/'logic.json').read_text());assert not result['errors']
classes=rules['class_bases']
def tr(values):return '<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in values)+'</tr>'
class_rows=''.join(tr([cid,s['name'],'特殊首领' if s['tier']==0 else s['tier'],s['base']]) for cid,s in classes.items())
boss_rows=''.join(tr([r['stage'],r['stage_name'],r['name'],r['level'],r['base'],r['value']]) for r in result['bosses'])
unit_rows=''.join(tr([r['stage'],r['unit'],r['name'],classes[str(r['class_id'])]['name'],r['level'],r['base'],r['value'],'首领' if r['boss'] else '普通／模板']) for r in result['units'])
files=['actual/core/enemy_experience.gd','actual/data/enemy_experience_20261104.json','actual/core/enemy_balance.gd','actual/core/game_state.gd','actual/tools/enemy_experience_data.py','actual/tools/sync_enemy_experience_20261104.py','actual/tools/build_chapter2_battles.py','actual/tools/build_chapter3.py','actual/tools/build_chapter4.py','actual/tools/build_chapter5.py','actual/tests/enemy_experience_20261104.gd','actual/tests/f21_feedback_20261104.gd','actual/tests/mechanical_puppets.gd']
