files+=['actual/'+m['path'].removeprefix('res://') for m in campaign['stages'].values()]
verification={'checks':result['checks'],'errors':[], 'stages':40, 'enemy_records_and_event_templates':len(result['units']),'bosses':40,'configured_classes':len(classes),'regressions':{'F21_feedback':345,'mechanical_puppets':59,'training':303,'M15_rewind':110},'source_sha256':{p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in files},'scope':result['scope'],'data_change_scope':'All40 authored stage files differ from before only in exp_value fields.'}
(OUT/'verification.json').write_text(json.dumps(verification,ensure_ascii=False,indent=2)+'\n')
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>敌方经验价值统一 · 2026-11-04</title><style>body{margin:0;background:#101923;color:#e9e7dc;font:16px/1.8 system-ui,sans-serif}main{max-width:1180px;margin:auto;padding:36px 24px}h1{font-size:30px}h2{color:#e7d59b;margin-top:38px}a{color:#a9d8fa}table{width:100%;border-collapse:collapse;background:#192635}th,td{padding:10px 14px;text-align:left;border-bottom:1px solid #35485a}th{color:#e7d59b;white-space:nowrap}.table{overflow-x:auto}code{color:#c7e8ff}input{font:inherit;padding:9px 14px;border:0;border-radius:7px;background:#e2e8ec;color:#182431;width:min(90%,600px);margin:12px 0}.muted{color:#b5c3cd}.ok{color:#b7e4b8}details{margin-top:28px}summary{cursor:pointer}</style><main><h1>敌方经验价值统一</h1><p class="muted">2026-11-04 · 用户最终确认表，执令术师追加为B＝50。未安装或更新iPhone。</p><p><code>V＝min(255，B＋floor(B×(敌人等级－1)÷10))</code></p><p>普通敌人按实际职业取B；40关首领使用确认的80～100基础值覆盖职业B。首领B不相加，最终V可以高于100。新部署、平衡修正、增援、召唤、旧存档、重试、回溯及交锋结算前均使用同一规则。</p><h2>职业基础值</h2><p>阶级是经验档位，不新增敌军转职。勇者为未投放的保留职业；公主尚未定义完整运行能力，保持不投放。</p><div class="table"><table><thead><tr><th>编号</th><th>职业</th><th>经验阶级</th><th>B</th></tr></thead><tbody>'''+class_rows+'''</tbody></table></div><h2>40关首领</h2><p>以下等级和V已按当前运行数值平衡后的职业／等级计算。关卡脚本中的历史缓存不会覆盖统一规则。</p><div class="table"><table><thead><tr><th>关卡</th><th>战场</th><th>首领</th><th>等级</th><th>B</th><th>V</th></tr></thead><tbody>'''+boss_rows+'''</tbody></table></div><h2>实际收益示例</h2><p>第二章首关：3级海兵与弓手V42，3级术士V60，3级水猴V60，5级指挥官V112。现有1级艾琳系数8×等级系数10，对应击杀经验分别为34、48、72（水猴含最终×1.5）和90。</p><p>水猴倍率、单次战斗经验100上限、角色系数、治疗和职业通关系数、关卡固定训练经验、乘客／双救20经验奖励均保留。补练对手保持V0；原有不提供经验的召唤物仍不给战斗经验，未因统一V开放刷经验。</p><h2>存档与验证</h2><p>只刷新敌军经验价值。当前血量、位置、行动状态和已结算经验保留，不追补或扣回旧收益。全部40张关卡只改exp_value字段，敌人数量、职业、属性、装备、AI、地图及任务条件不变。</p>'''+f'''<p class="ok">定向检查{result['checks']}项通过，覆盖40关、{len(result['units'])}条敌军／增援／事件模板及40名首领。既有F21检查345项、机械傀儡59项、补练303项、M15回溯110项通过。</p><p>本轮为数值与存档逻辑修改，使用无窗口检查；未做完整战役通关或真机验证。</p><p><a href="logic.json">全部检查与逐单位记录</a> · <a href="verification.json">范围与源码校验</a> · <a href="../../data/enemy_experience_20261104.json">统一配置</a> · <a href="../../core/enemy_experience.gd">运行公式</a></p><details><summary>全部{len(result['units'])}条敌军／事件模板，支持搜索</summary><input id="filter" placeholder="搜索关卡、单位、职业…" aria-label="搜索敌军记录"><div class="table"><table id="units"><thead><tr><th>关卡</th><th>单位ID</th><th>名称</th><th>职业</th><th>等级</th><th>B</th><th>V</th><th>类别</th></tr></thead><tbody>'''+unit_rows+'''</tbody></table></div></details></main><script>document.querySelector('#filter').addEventListener('input',e=>{let q=e.target.value.toLowerCase();for(let r of document.querySelectorAll('#units tbody tr'))r.hidden=!r.textContent.toLowerCase().includes(q)});</script></html>'''
(OUT/'index.html').write_text(page)
print(json.dumps({k:verification[k]for k in ['checks','stages','enemy_records_and_event_templates','bosses','configured_classes']},ensure_ascii=False))
